#include <print>

int main() {
    int counter = 0;
    auto bump = [&counter] { counter++; };      // 留一根线：写的就是外面那只盒子
    bump();
    bump();
    std::println("counter = {}", counter);

    // auto bad = [counter] { counter++; };   ← 把 & 抹掉再编译：拦在编译期
    // 报错是 cannot assign to variable counter in lambda capture of type const int：只读的是包里那份复印件
    return 0;
}

